// 초당 채워지는 양(rate)과 최대 저장량(burst)
function allow(state, now, rate = 5, burst = 10) {
  const elapsed = (now - state.last) / 1000;
  state.tokens = Math.min(burst, state.tokens + elapsed * rate); // 채우기
  state.last = now;
  if (state.tokens >= 1) { state.tokens -= 1; return true; }     // 쓰기
  return false;                                                    // 429
}
// 상태(tokens, last)는 사용자/키별로 저장 (분산이면 Redis, 7장)
